over=dict(status='usable',rationale='Representative formation and authority paths, their history/membership coupling and application boundaries are traced. Local questions and variants remain open; this is not coverage or correctness certification.',formation=dict(explanation='Node/Peer proposals reach the leader, which appends current-term entries and sends predecessor-qualified replication. Followers reject mismatching prefixes or append matching entries, protect committed history and acknowledge accepted indexes. Engine persists ordinary responses before sending them (replication requests may precede persistence). Leader aggregates full-member and witness match values, selects the quorum index and commits only a current-term entry there, thereby carrying its prefix. Commit is propagated in replication/heartbeat messages; committed entries pass through a separate RSM queue to membership/application processing and client callbacks. Rejections retry with lower next; compacted histories use snapshots for active peers.',behavior_ids=['B-formation','B-persistence','B-apply','B-recovery'],fact_ids=['F-committed'],source_ids=['S-formation','S-log','S-replication-send','S-replication-recv','S-engine-order','S-node-effects','S-rsm-apply']),context=dict(explanation='Election ticks on eligible full members trigger term increment and self-vote. Vote grants require vote eligibility and log freshness; known response admission and unique sender counting qualify election support. Promotion resets progress and adds a current-term no-op. Higher-term messages normally relinquish authority; stale terms are rejected, with a recent-leader exception for higher-term vote requests. Configured quorum checks revoke inactive leadership. Transfer pauses proposals, waits for a full target to catch up and sends TimeoutNow; timeout cancels transfer. Reset drops volatile pending reads and votes while retaining log history. Application of removal revokes local leadership; restart restores persisted term/vote/commit and snapshot membership.',behavior_ids=['B-authority','B-membership','B-recovery','B-persistence'],source_ids=['S-formation','S-term','S-peer-admission','S-ticks','S-transfer','S-check-quorum','S-membership','S-recovery']),connection=dict(explanation='Only support qualified by current term/role and current membership advances formation; remote progress is rebuilt on authority reset while committed log history constrains future leaders through freshness and prefix checks. Pending configuration entries limit new proposals, and committed-but-unapplied work suppresses campaigning to avoid stale membership authority. RSM accepts legal configuration transitions then updates raft quorum membership. ReadIndex separately confirms current leadership only after current-term commitment, probes voting members and resolves a queued prefix; application and exact request context determine client completion. Old nonzero-term replies are filtered, pending read support is discarded on reset, and old log entries remain recoverable rather than being treated as current quorum proof.',behavior_ids=['B-formation','B-authority','B-membership','B-read-admit','B-read-confirm','B-read-deliver','B-read-client'],fact_ids=['F-committed','F-pending-read','F-confirmed-read'],source_ids=['S-term','S-formation','S-membership','S-rsm-config','S-read-consume','S-read-queue','S-read-response','S-client-batches']),open_details=['Remote read-index queue-prefix response context and request correlation.','Read confirmation support spanning membership changes; legal schedules and retained confirmations need investigation.','Logdb crash atomicity, session replay and on-disk state-machine variants remain local unread details.'],core_gaps=[])
m=dict(version=1,target_profile=dict(system_boundary='Captured Dragonboat Go module: node/engine, internal Raft, RSM, storage and client-facing read completion; network, storage backend and application boundaries are implementation interfaces, not assumed correct.',protocol_contexts=['Per-cluster term/role/log/membership','ReadIndex SystemCtx and node-local request batches'],ownership=['Raft state machine owns election, replication and read confirmation; engine coordinates persistence/transport; RSM owns application and membership acceptance.'],variants=['Full voting node','Non-voting observer','Voting metadata witness','In-memory, concurrent and on-disk application state machines'],source_ids=['S-quorum','S-recovery','S-rsm-apply','S-read-api']),activities=acts,behaviors=beh,facts=facts,core_overview=over,surfaces=[dict(entry_point='raft.handleReadIndexLeaderConfirmation',disposition='mapped',behavior_ids=['B-read-confirm','B-read-deliver'],reason='Why do remote responses use the triggering context while confirmed statuses retain distinct contexts?',source_ids=['S-read-response','S-read-queue'],high_consequence=False),dict(entry_point='raft.handleNodeConfigChange/readIndex.confirm',disposition='deferred',reason='Determine which pending confirmation support remains eligible across legal membership changes.',source_ids=['S-membership','S-read-queue'],high_consequence=True)])
